import logging
from . import bip_trace
from . import robot_listener


logger = logging.getLogger()


class collection(object):
    """
    This library collects the Bts Internal Protocol Trace (BIP Trace)
    on a gnb. It determines the current hardware configuration
    (ASOE, ASIB-ABIL,...) and executes the corresponding mirror
    commands on the Airscale, before the start of the tcpdump is
    executed to start the trace collection.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 3

    def __init__(self, tl_config=None):
        bip_trace.set_testline_configuration(tl_config)
        self.use_script = False
        self.bip_scripts_path = None
        self.bip_scripts_parameter = None
        self.ROBOT_LIBRARY_LISTENER = robot_listener.RobotEventListener()

    def configure_bip_collection(self, **configuration_params):
        """
        Configure the bip trace collection. To shorten the setup time, information like
        the system_module may be provided. See also the example page.

        The use of the key gNB_common_unit is deprecated, system_module should be used instead.

        The use of the key gNB_capacity_units is deprecated, baseband_modules should be used instead.

        See "Examples" for a list of all possible configuration parameters.


        .. code-block:: robotframework

            ${capacity_units}=  Create List    ABIO

            Configure Bip Collection   l1_type=FS
            ...                        gNB_common_unit=ASIB
            ...                        gNB_capacity_units=${capacity_units}
            ...                        use_script=True
            ...                        script_parameters=--bb_slot_1='false' --bb_slot_2='true' --bb_slot_3='false'

        """
        bip_trace.configure_bip_collection(**configuration_params)

    def use_mirror_script(self, use_script=True):
        """
        Keyword to enable the usage of the bash script to execute the
        port mirroring and collection of logs. The library will directly
        upload the scripts gnbMirroring.sh with its configuration script and
        execute it on the system module.

        :param use_script: Boolean parameter to set usage of script, default is ${True}
        """
        bip_trace.configure_bip_collection(use_script=use_script)

    def start_bip_trace(self, gnb_id=0):
        """
        Start the BIP trace on a gnb identified by its gnb_id of
        the testline configuration.

        :param int gnb_id: the gnb_id given in testline config for gnb identification
        """
        logger.info("Starting BIP Trace Collection")
        return bip_trace.start_bip_trace(gnb_id)

    def stop_bip_trace(self, target_dir='/tmp', gnb_id=0):
        """
        Stops the bip trace. Since there can be more captured pcap files, a list of pcap files is returned.

        :param int gnb_id: the gnb_id of testline configuration
        :param str target_dir: the target direcory, where the pcap shall be stored in, default is /tmp
        :return: List of pcap file paths
        """
        logger.info("Stopping BIP Trace Collection")
        return bip_trace.stop_bip_trace(gnb_id, target_dir)

    def collect_bip_trace(self, target_dir='/tmp', gnb_id=0):
        """
        Collect the bip trace. You can separate the collection of the bip trace from the call of the
        keyword "Stop Bip Trace" by the configuration flag "collect_separately"

        :param int gnb_id: the gnb_id of testline configuration
        :param str target_dir: the target direcory, where the pcap shall be stored in, default is /tmp
        :return: List of pcap file paths
        """
        logger.info("Collecting BIP Traces")
        return bip_trace.collect_bip_trace(gnb_id=gnb_id, target_dir=target_dir)
